using Microsoft.EntityFrameworkCore;

namespace SportsCourtBooking.Infrastructure.Data;

public static class OwnerFacilitySchemaExtensions
{
    private const string FacilitySchemaSql = """
        CREATE TABLE IF NOT EXISTS "Facilities" (
            "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            "OwnerId" integer NULL REFERENCES "Users" ("Id") ON DELETE SET NULL,
            "Name" character varying(150) NOT NULL,
            "Address" character varying(255) NOT NULL,
            "Description" character varying(1000) NULL,
            "CreatedAt" timestamp with time zone NOT NULL,
            "UpdatedAt" timestamp with time zone NULL
        );

        ALTER TABLE "Facilities"
            ADD COLUMN IF NOT EXISTS "PhoneNumber" character varying(30) NOT NULL DEFAULT '',
            ADD COLUMN IF NOT EXISTS "OpenTime" character varying(10) NOT NULL DEFAULT '06:00',
            ADD COLUMN IF NOT EXISTS "CloseTime" character varying(10) NOT NULL DEFAULT '22:00',
            ADD COLUMN IF NOT EXISTS "ImageUrl" character varying(500) NULL,
            ADD COLUMN IF NOT EXISTS "IsApproved" boolean NOT NULL DEFAULT true,
            ADD COLUMN IF NOT EXISTS "IsActive" boolean NOT NULL DEFAULT true,
            ADD COLUMN IF NOT EXISTS "SuspensionReason" character varying(500) NULL;

        ALTER TABLE "Facilities"
            ALTER COLUMN "OwnerId" DROP NOT NULL;

        ALTER TABLE "Courts"
            ADD COLUMN IF NOT EXISTS "FacilityId" integer NULL;

        DO $$
        BEGIN
            IF EXISTS (
                SELECT 1
                FROM pg_constraint
                WHERE conname = 'FK_Courts_Facilities_FacilityId'
                  AND conrelid = '"Courts"'::regclass
                  AND confdeltype <> 'r'
            ) THEN
                ALTER TABLE "Courts"
                    DROP CONSTRAINT "FK_Courts_Facilities_FacilityId";
            END IF;

            IF NOT EXISTS (
                SELECT 1
                FROM pg_constraint
                WHERE conname = 'FK_Courts_Facilities_FacilityId'
                  AND conrelid = '"Courts"'::regclass
            ) THEN
                ALTER TABLE "Courts"
                    ADD CONSTRAINT "FK_Courts_Facilities_FacilityId"
                    FOREIGN KEY ("FacilityId") REFERENCES "Facilities" ("Id") ON DELETE RESTRICT;
            END IF;
        END $$;

        CREATE INDEX IF NOT EXISTS "IX_Facilities_OwnerId" ON "Facilities" ("OwnerId");
        CREATE INDEX IF NOT EXISTS "IX_Courts_FacilityId" ON "Courts" ("FacilityId");
        """;

    public static Task EnsureOwnerFacilitySchemaAsync(
        this AppDbContext db,
        CancellationToken cancellationToken = default)
    {
        if (!db.Database.IsNpgsql())
        {
            throw new InvalidOperationException("Owner facility schema requires PostgreSQL.");
        }

        return db.Database.ExecuteSqlRawAsync(FacilitySchemaSql, cancellationToken);
    }
}
